#include "ashes/contracts.hpp"
#include <cstring>
namespace ashes {
static void varint(Bytes& b,uint64_t n){while(n>=128){b.push_back(uint8_t(n)|128);n>>=7;}b.push_back(uint8_t(n));}static uint64_t varint(const Bytes& b,size_t& pos){uint64_t v=0;for(int s=0;s<70;s+=7){require(pos<b.size(),"Truncated protobuf");uint8_t n=b[pos++];if(s==63)require(n<2,"Protobuf overflow");v|=uint64_t(n&127)<<s;if(!(n&128))return v;}throw std::runtime_error("Overlong protobuf varint");}
static int wire(int type){if(type==1||type==6||type==16)return 1;if(type==2||type==7||type==15)return 5;if(type==9||type==11||type==12)return 2;return 0;}
Bytes Contracts::encode(const std::string& name,const Json& values)const{auto& fields=schema.at(name).at("fields");Bytes result;for(auto it=fields.begin();it!=fields.end();++it){if(!values.contains(it.key())||values.at(it.key()).is_null())continue;auto& f=it.value();int type=f.at("type"),number=f.at("number"),w=wire(type);auto put=[&](const Json& v){Bytes b;uint64_t n=0;if(w==0){if(type==8)n=v.get<bool>();else if(type==3||type==5||type==14)n=uint64_t(v.get<int64_t>());else if(type==17||type==18){int64_t s=v.get<int64_t>();n=(uint64_t(s)<<1)^uint64_t(s>>63);}else n=v.get<uint64_t>();if(n==0)return;varint(b,n);}else if(w==2){if(type==11)b=encode(f.at("message"),v);else if(type==12)b=unhex(v.get<std::string>());else{auto s=v.get<std::string>();b.assign(s.begin(),s.end());}if(b.empty())return;}else{b.resize(w==1?8:4);if(type==1){double d=v;std::memcpy(b.data(),&d,8);}else if(type==2){float d=v;std::memcpy(b.data(),&d,4);}else{n=v.get<uint64_t>();std::memcpy(b.data(),&n,b.size());}if(std::all_of(b.begin(),b.end(),[](uint8_t c){return c==0;}))return;}varint(result,uint64_t(number)*8+w);if(w==2)varint(result,b.size());result.insert(result.end(),b.begin(),b.end());};auto& v=values.at(it.key());if(f.at("map")==true){for(auto m=v.begin();m!=v.end();++m)put(Json{{"key",m.key()},{"value",m.value()}});}else if(f.at("repeated")==true){for(auto& a:v)put(a);}else put(v);}return result;}
Json Contracts::decode(const std::string& name,const Bytes& data)const{auto& fields=schema.at(name).at("fields");std::map<int,std::pair<std::string,Json>> by;for(auto i=fields.begin();i!=fields.end();++i)by[i.value().at("number")]={i.key(),i.value()};Json result=Json::object();size_t pos=0;while(pos<data.size()){auto tag=varint(data,pos);int number=int(tag>>3),w=tag&7;require(number>0,"Protobuf field zero");uint64_t n=0;Bytes b;if(w==0)n=varint(data,pos);else if(w==1||w==5){size_t k=w==1?8:4;require(k<=data.size()-pos,"Truncated fixed protobuf");b.assign(data.begin()+pos,data.begin()+pos+k);std::memcpy(&n,b.data(),k);pos+=k;}else if(w==2){auto k=varint(data,pos);require(k<=data.size()-pos,"Truncated bytes protobuf");b.assign(data.begin()+pos,data.begin()+pos+size_t(k));pos+=size_t(k);}else throw std::runtime_error("Unsupported protobuf wire type");if(!by.contains(number))continue;auto [key,f]=by.at(number);int type=f.at("type");Json value;if(type==11)value=decode(f.at("message"),b);else if(type==9)value=std::string(b.begin(),b.end());else if(type==12)value=hex(b);else if(type==1){double d;std::memcpy(&d,b.data(),8);require(std::isfinite(d),"Nonfinite protobuf double");value=d;}else if(type==2){float d;std::memcpy(&d,b.data(),4);require(std::isfinite(d),"Nonfinite protobuf float");value=d;}else if(type==8)value=bool(n);else if(type==17||type==18)value=int64_t((n>>1)^uint64_t(-int64_t(n&1)));else if(type==3||type==5||type==14)value=int64_t(n);else value=n;if(f.at("map")==true)result[key][value.value("key","")]=value.value("value",Json());else if(f.at("repeated")==true){if(!result.contains(key))result[key]=Json::array();result[key].push_back(value);}else result[key]=value;}return result;}
}
